create table public.references(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,source_url text not null,media_type text not null,media_url text,embed_html text,tags text[] not null default '{}',palette text[] not null default '{}',note text not null default '',title text,added timestamptz not null default now(),media_incomplete boolean not null default false,unique(user_id,source_url)); alter table public.references enable row level security; create policy "own references" on public.references for all using(auth.uid()=user_id) with check(auth.uid()=user_id); insert into storage.buckets(id,name,public) values('reference-media','reference-media',true) on conflict(id) do nothing; create policy "public media" on storage.objects for select using(bucket_id='reference-media');